use std::io::{BufRead, BufReader, Read, Write};
use std::net::{SocketAddr, TcpListener, TcpStream};
use std::thread;

const HELLO: &str = "<html><body><h1>Hello!</h1><p>Hi from Rust</p></body></html>";
const NOT_FOUND: &str = "<html><body><h1>Oops!</h1><p>Sorry, I don't know what you're asking for.</p></body></html>";

fn handle_connection(mut stream: TcpStream) {
    let request: Vec<String> = BufReader::new(&stream)
        .lines()
        .map(|line| line.unwrap())
        .take_while(|line| !line.is_empty())
        .collect();

    let (status_line, contents) = if request[0] == "GET / HTTP/1.1" {
        ("HTTP/1.1 200 OK", HELLO)
    } else {
        ("HTTP/1.1 404 NOT FOUND", NOT_FOUND)
    };

    let length = contents.len();
    let response = format!("{status_line}\r\nContent-Length: {length}\r\n\r\n{contents}");
    stream.write_all(response.as_bytes()).unwrap();
}

fn get(addr: SocketAddr, path: &str) -> String {
    let mut s = TcpStream::connect(addr).unwrap();
    write!(s, "GET {path} HTTP/1.1\r\nHost: localhost\r\n\r\n").unwrap();
    let mut reply = String::new();
    s.read_to_string(&mut reply).unwrap();
    reply
}

fn main() {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let addr = listener.local_addr().unwrap();
    let server = thread::spawn(move || {
        for stream in listener.incoming().take(2) {
            handle_connection(stream.unwrap());
        }
    });

    for path in ["/", "/missing"] {
        let reply = get(addr, path);
        let (head, body) = reply.split_once("\r\n\r\n").unwrap();
        println!("{path}  ->  {}", head.replace("\r\n", " / "));
        println!("{body}\n");
    }
    server.join().unwrap();
}

fn respond(request_line: &str) -> String {
    let (status, body) = match request_line {
        "GET / HTTP/1.1" => ("200 OK", "<h1>Hello!</h1>"),
        _ => ("404 NOT FOUND", "not found"),
    };
    format!("HTTP/1.1 {status}\r\nContent-Length: {}\r\n\r\n{body}", body.len())
}

fn main() {
    for line in ["GET / HTTP/1.1", "GET /about HTTP/1.1", "GET /nope HTTP/1.1"] {
        let response = respond(line);
        let status = response.lines().next().unwrap().trim_start_matches("HTTP/1.1 ");
        let length = response.split("\r\n\r\n").nth(1).unwrap().len();
        println!("{status} {length}");
    }
}
